# InDesign JSX Script: Convert Spreads to Single Pages

Here's an optimized JSX script for Adobe InDesign that converts a document with spreads (facing pages) into a single-page document while preserving all layout elements, margins, and master page references:

```jsx
//@targetengine "session"
//@target indesign

/**
 * Converts a spreads-based InDesign document to single pages while preserving:
 * - All original margins and layout
 * - Element positioning
 * - Master page references
 * - Layer structure
 * - Object styles and formatting
 */

(function() {
    // Check if a document is open
    if (app.documents.length === 0) {
        alert("No documents are open. Please open a document and try again.");
        return;
    }

    var doc = app.activeDocument;
    var originalDocument = doc;
    var originalRulerOrigin = doc.rulerOrigin;
    var originalZeroPoint = doc.zeroPoint;
    var originalPageWidth = doc.documentPreferences.pageWidth;
    var originalPageHeight = doc.documentPreferences.pageHeight;
    var originalFacingPages = doc.documentPreferences.facingPages;
    var originalPageCount = doc.pages.length;

    // Store original master spreads
    var masterSpreads = [];
    for (var i = 0; i < doc.masterSpreads.length; i++) {
        masterSpreads.push(doc.masterSpreads[i]);
    }

    // Store original page items with their properties
    var pageItemsData = [];
    for (var p = 0; p < doc.pages.length; p++) {
        var page = doc.pages[p];
        var pageItems = page.pageItems.everyItem().getElements();

        for (var i = 0; i < pageItems.length; i++) {
            var item = pageItems[i];
            pageItemsData.push({
                item: item,
                page: page,
                geometricBounds: item.geometricBounds,
                itemLayer: item.itemLayer,
                locked: item.locked,
                hidden: item.hidden,
                // Store more properties as needed
            });
        }
    }

    try {
        // Begin undo group
        app.doScript(function() {
            // Convert to single pages
            doc.documentPreferences.facingPages = false;

            // Process each spread (now single pages)
            for (var s = doc.spreads.length - 1; s >= 0; s--) {
                var spread = doc.spreads[s];

                // Skip if spread has only one page (already single)
                if (spread.pages.length <= 1) continue;

                // For each page in the spread (except first)
                for (var p = spread.pages.length - 1; p >= 1; p--) {
                    var page = spread.pages[p];
                    var items = page.pageItems.everyItem().getElements();

                    // Move items to the previous page
                    var prevPage = spread.pages[p - 1];

                    // Adjust geometric bounds for items moving to previous page
                    for (var i = 0; i < items.length; i++) {
                        var item = items[i];
                        var bounds = item.geometricBounds;
                        var newBounds = [
                            bounds[0] - originalPageWidth, // left
                            bounds[1],                    // top
                            bounds[2] - originalPageWidth, // right
                            bounds[3]                     // bottom
                        ];

                        item.move(prevPage);
                        item.geometricBounds = newBounds;
                    }

                    // Remove the now-empty page
                    page.remove();
                }
            }

            // Reapply master pages to maintain references
            for (var p = 0; p < doc.pages.length; p++) {
                var page = doc.pages[p];
                var originalMaster = page.appliedMaster;

                if (originalMaster !== null) {
                    // Find the corresponding single-page master
                    var masterName = originalMaster.name;
                    var singleMaster = null;

                    // Look for a master with the same name but for single pages
                    for (var m = 0; m < doc.masterSpreads.length; m++) {
                        var ms = doc.masterSpreads[m];
                        if (ms.name === masterName && ms.pages.length === 1) {
                            singleMaster = ms.pages[0];
                            break;
                        }
                    }

                    // If no exact match found, use the first page of the original master
                    if (singleMaster === null && originalMaster.pages.length > 0) {
                        singleMaster = originalMaster.pages[0];
                    }

                    if (singleMaster !== null) {
                        page.appliedMaster = singleMaster;
                    }
                }
            }

            // Restore original ruler origin and zero point
            doc.rulerOrigin = originalRulerOrigin;
            doc.zeroPoint = originalZeroPoint;

        }, "Convert Spreads to Single Pages", {commandName: "ConvertSpreadsToSinglePages"});

        // Show completion message
        alert("Successfully converted " + originalPageCount + " pages from spreads to single pages.\n" +
              "Original page count: " + originalPageCount + "\n" +
              "New page count: " + doc.pages.length);

    } catch (e) {
        // Revert changes if error occurs
        try {
            doc.documentPreferences.facingPages = originalFacingPages;
        } catch (revertError) {
            // If we can't revert, at least inform the user
            alert("Error during conversion: " + e.message + "\n" +
                  "Could not revert document settings: " + revertError.message);
            return;
        }

        alert("Error during conversion: " + e.message + "\n" +
              "Document has been reverted to its original state.");
    }
})();
```

## Key Features of This Script:

1. **Preservation of All Elements**:
   - Maintains all page items (text frames, images, shapes, etc.)
   - Keeps original positioning by adjusting coordinates when moving items
   - Preserves layer structure and object properties

2. **Master Page Handling**:
   - Attempts to match original master pages to single-page versions
   - Falls back to using the first page of original master spreads if no exact match exists

3. **Document Settings**:
   - Maintains original margins and ruler origins
   - Preserves all document preferences except facingPages

4. **Error Handling**:
   - Includes try-catch blocks to handle errors gracefully
   - Attempts to revert changes if something goes wrong

5. **Performance Optimizations**:
   - Processes spreads from last to first to maintain correct page numbering
   - Uses efficient loops and minimizes DOM access

## How to Use:

1. Open your InDesign document with spreads
2. Run this script (via Scripts panel or ExtendScript Toolkit)
3. The document will be converted to single pages while preserving all content

## Notes:

- The script creates an undo step, so you can revert if needed
- For complex documents with many master pages, you might need to manually adjust some master page assignments after conversion
- Test on a copy of your document first, especially for critical projects

